import {mountVirtualSystems} from './virtual-systems.js';
import {renderWorldBuilder,bindWorldBuilder} from './world-builder.js';
const $=id=>document.getElementById(id), esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>x==null?'—':Number(x).toLocaleString(), money=(x,c='CAD')=>x==null?'—':new Intl.NumberFormat('en-CA',{style:'currency',currency:c}).format(x/100);
const params=new URLSearchParams(location.search);
let catalog=[],selected=params.get('town')||sessionStorage.getItem('atlas-town'),summary,bills,virtualReady=null,page=location.hash.slice(1)||'map',busy=false,property,version=0,propertyVersion=0,toastTimer,billingOffset=0;
let backend=sessionStorage.getItem('atlas-backend')||'',token=sessionStorage.getItem('atlas-token')||'';
const apiBase=()=>backend.replace(/\/$/,'');
function capture(){const context={town:selected,base:apiBase(),token,version,summary,virtualReady};context.current=()=>context.version===version&&context.town===selected&&context.base===apiBase()&&context.token===token;context.api=(path,body)=>api(path,body,context);return context;}
async function api(path,body,context=capture()){if(!context.current())throw Error('The selected town or runtime changed.');const url=new URL(context.base+'/atlas/api/'+path,location.origin);if(context.town)url.searchParams.set('town',context.town);const response=await fetch(url,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(context.token?{'Authorization':'Bearer '+context.token}:{})},...(body?{body:JSON.stringify(body)}:{})});let value;try{value=await response.json();}catch{throw Error(response.ok?'The durable runtime is not connected. Configure its address in Connections.':`The runtime returned HTTP ${response.status}. Check its server log; retrying a saved command is safe.`);}if(!response.ok)throw Error(typeof value.detail==='string'?value.detail:'The runtime could not complete this request.');return value;}
function notice(text){$('notice').textContent=text;$('notice').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('notice').classList.remove('visible'),8000);}
const row=(label,value)=>`<div class="record-row"><span>${esc(label)}</span><b>${esc(value)}</b></div>`;
const card=(label,value,note='')=>`<div class="card"><small>${esc(label)}</small><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`;
const tag=text=>`<span class="tag ${esc(text)}">${esc(text)}</span>`;
function mapConfig(){return {type:'atlas-runtime',presetId:selected,apiBase:apiBase(),token};}
function setMap(){const url=new URL('/presets/shared/tiled-map.html',location.origin);url.searchParams.set('preset',selected);const initial=params.get('premise');if(initial&&(!params.get('town')||params.get('town')===selected))url.searchParams.set('premise',initial);$('town-map').src=url;}
$('town-map').addEventListener('load',()=>$('town-map').contentWindow.postMessage(mapConfig(),location.origin));
async function loadTown(id){selected=id;sessionStorage.setItem('atlas-town',id);const url=new URL(location);url.searchParams.set('town',id);history.replaceState(null,'',url);$('town').value=id;const entry=catalog.find(t=>t.id===id);$('character').textContent=entry?.character||'';summary=null;bills=null;virtualReady=null;property=null;propertyVersion++;busy=false;$('property').close();setMap();version++;const context=capture();$('connection-status').textContent='Opening saved world…';$('map-status').textContent='Opening '+(entry?.name||id)+' · first initialization may take several minutes';render();try{const data=await context.api('summary');if(!context.current())return context;summary=data;$('connection-status').textContent='Persistent runtime connected';$('map-status').textContent=`${entry?.name||id} · ${fmt(data.town.homes)} homes · ${fmt(data.state.days)} simulated days · ${fmt(data.state.observations)} meter observations`;try{const integration=await context.api('integration');if(!context.current())return context;virtualReady=integration.virtualSystems;}catch{if(!context.current())return context;}await loadBilling(context);if(!context.current())return context;render();if(page==='quality')loadQuality();}catch(e){if(!context.current())return context;$('connection-status').textContent='Runtime unavailable';$('map-status').textContent=e.message;render();notice(e.message);}return context;}
async function loadBilling(context=capture()){if(!context.current()||!summary)return;const result=await context.api('billing?offset='+billingOffset);if(context.current())bills=result;}
function navigate(next){page=['map','overview','billing','preview','virtual','configure','quality','connections'].includes(next)?next:'map';history.replaceState(null,'','#'+page);document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));$('map-page').hidden=page!=='map';$('content-page').hidden=page==='map';render();if(page==='quality'&&summary)loadQuality();}
function controls(){return `<button class="primary" data-action="advance" ${busy||!summary?.state.manualAdvanceAllowed?'disabled':''}>Simulate next day</button>`;}
function render(){$('content')._virtualMarker=null;if(page==='map')return;const entry=catalog.find(t=>t.id===selected);$('title').textContent=({overview:entry?.name||'Your world',billing:virtualReady?.configured?'Virtual Systems billing & receivables':'Local charge preview',preview:'Local charge preview',virtual:'Virtual Systems billing & receivables',configure:'The world behind the map',quality:'Quality checks',connections:'Connect the runtime'})[page];$('subtitle').textContent=summary?`${fmt(summary.town.homes)} homes · ${fmt(summary.town.premises)} premises · next physical day ${summary.state.through}`:'Map preview is available independently. Connect the durable runtime to simulate, bill and resolve issues.';const disabled=busy||!summary?'disabled':'';
if(page==='overview')$('content').innerHTML=summary?`<div class="cards">${card('Homes',fmt(summary.town.homes))}${card('Customer accounts',fmt(summary.town.accounts))}${card('Physical meters',fmt(summary.state.assets))}${card('Completed days',fmt(summary.state.days))}</div><div class="panel"><h2>A saved world that changes each day</h2><p>Advance the physical world, receive its meter observations, then calculate bills using the configured tariffs. Each step is persistent and independently visible.</p><div class="actions">${controls()}<button data-action="ingest" ${disabled}>Receive meter reads</button><button data-page="billing">Open billing workspace</button></div></div><div class="panel"><h2>Recent physical activity</h2>${summary.state.events.slice(0,12).map(e=>row(e.day,e.type+' · '+e.subject)).join('')}</div>`:`<div class="panel"><p>Choose a baked town and connect its runtime in Connections.</p><button data-page="connections">Connections</button></div>`;
if(page==='preview'||(page==='billing'&&!virtualReady?.configured)){$('content').innerHTML=`<div class="cards">${card('Received meter reads',fmt(bills?.receivedReads),'Observations only; never physical truth')}${card('Issued bill documents',fmt(bills?.issuedDocuments),money(bills?.issuedAmountCents))}${card('Blocked documents',fmt(bills?.blockedDocuments),'Missing reads remain unresolved')}${card('Missing received reads',fmt(bills?.missingReads))}</div><div class="panel"><h2>Run the observation-to-bill process</h2><div class="actions">${controls()}<button data-action="ingest" ${disabled}>Receive meter reads</button><label>Period start<input type="date" id="bill-start" value="${esc(bills?.nextPeriodStart||'2026-01-01')}"></label><label>End (exclusive)<input type="date" id="bill-end" value="${esc(summary?.state.through||'2026-01-08')}"></label><button class="primary" data-action="bill" ${disabled}>Calculate bills</button></div><p class="subtle">Dates include the start and exclude the end. Issued periods cannot overlap. These local simulation bill documents use UtilitySim tariffs and are not posted to an external billing provider.</p></div><div class="panel"><h2>Billing documents</h2>${documents(bills?.documents||[])}</div><div class="panel"><h2>Missing-read cases</h2>${cases(bills?.cases||[])}</div><div class="panel"><h2>Latest received observations</h2>${reads(bills?.reads||[])}</div>`;}
if(page==='configure')$('content').innerHTML=`<div class="panel"><h2>Saved town configuration</h2><p>Geometry and identities are fixed for this version. Changing geography requires a new version and an explicit migration of saved accounts.</p><pre>${esc(JSON.stringify(summary?.town.design||entry,null,2))}</pre></div><details class="panel"><summary>Engine configuration</summary><pre>${esc(JSON.stringify(summary?.town.config||{},null,2))}</pre></details>`;
if(page==='quality')$('content').innerHTML=`<div class="panel"><h2>${entry?.internalVisualReview?.status==='passed'?'Internal visual QA passed':'Internal visual QA pending'}</h2><p>${entry?.userVisualApproval?'User accepted this map.':'Optional user acceptance is pending.'}</p></div><div class="panel" id="quality-results"><p>Open the saved runtime to run geometry and persistence checks.</p></div>`;
if(page==='connections')$('content').innerHTML=`<div class="panel"><h2>Durable UtilitySim runtime</h2><p>The map can be hosted as static files. Simulation, received reads, billing and physical work require a persistent backend. The current browser can connect to a configured runtime.</p><form id="connection-form"><label>Runtime URL (blank uses this server)<input id="backend" type="url" placeholder="https://runtime.example.com" value="${esc(backend)}"></label><label>Runtime API access token<input id="token" type="password" autocomplete="off" value="${esc(token)}"></label><button class="primary">Connect</button></form><p class="subtle">Address and token are kept for this browser tab session. Hosted runtimes require TLS, an allowed origin and API authentication.</p></div><div class="panel"><h2>Virtual Systems / external billing</h2><p>Open the Virtual Systems workspace to inspect the actual configured recipient. The local UtilitySim tariff workbench and Virtual Systems maintain separate financial records.</p><p>Integration export: <code>/atlas/api/observations?town=${esc(selected)}&start=YYYY-MM-DD&end=YYYY-MM-DD</code>. Exports contain observations, never hidden physical truth. Automatic shared scheduling is a separate deployment from the local recipient workflow.</p></div>`;
if(page==='configure')$('content').insertAdjacentHTML('afterbegin',renderWorldBuilder(entry));
if((page==='preview'||(page==='billing'&&!virtualReady?.configured))&&bills){$('content').insertAdjacentHTML('beforeend',`<div class="actions"><button id="billing-prev" ${busy||billingOffset===0?'disabled':''}>Newer records</button><span class="subtle">Rows ${billingOffset+1}–${billingOffset+50} in each list</span><button id="billing-next" ${busy||Math.max(bills.receivedReads,bills.issuedDocuments+bills.blockedDocuments,bills.missingReads)<=billingOffset+50?'disabled':''}>Older records</button></div>`);$('billing-prev').onclick=()=>billingPage(-50);$('billing-next').onclick=()=>billingPage(50);}
if(page==='connections')$('content').insertAdjacentHTML('beforeend','<div class="panel"><h2>Hosted page and localhost</h2><p>Use an HTTPS runtime with the hosted HTTPS shell. Browsers can block access from a hosted page to a local computer or require local-network permission. If the local connection is blocked, open the shell on the runtime itself at <code>http://127.0.0.1:8044/</code>. The public map preview continues to work independently.</p></div>');
bind();bindWorldBuilder(notice);if(page==='virtual'||(page==='billing'&&virtualReady?.configured)){const context=capture();mountVirtualSystems($('content'),{api:context.api,summary,notice:text=>{if(context.current())notice(text);},onPremise:id=>{if(context.current())openProperty(id);},onAdvance:()=>{if(context.current())action('advance');}});}}
async function billingPage(change){if(busy)return;const context=capture();billingOffset=Math.max(0,billingOffset+change);busy=true;try{await loadBilling(context);}catch(e){if(context.current())notice(e.message);}finally{if(context.current()){busy=false;render();}}}
function connectRuntime(e){e.preventDefault();const candidate=$('backend').value.trim();if(candidate){try{const url=new URL(candidate);if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw Error();if(location.protocol==='https:'&&url.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(url.hostname)){notice('Use an HTTPS runtime for this hosted HTTPS page.');return;}}catch{notice('Enter an HTTP or HTTPS runtime address without embedded credentials or query parameters.');return;}}backend=candidate;token=$('token').value;sessionStorage.setItem('atlas-backend',backend);sessionStorage.setItem('atlas-token',token);billingOffset=0;initialize();}
function documents(items){return items.length?`<div class="scroll"><table><thead><tr><th>PREMISE / ACCOUNT</th><th>PERIOD</th><th>SERVICE</th><th>AMOUNT</th><th>STATE</th></tr></thead><tbody>${items.map(d=>`<tr><td><button data-premise="${esc(d.premiseId)}">${esc(d.premiseId)}</button><br><code>${esc(d.accountId)}</code></td><td>${esc(d.start)} → ${esc(d.end)}</td><td>${esc(d.commodity)}</td><td>${money(d.amountCents,d.currency)}</td><td>${tag(d.status)}<details><summary>Evidence</summary>${esc(d.reason||'Calculated from '+d.sourceObservationIds.length+' received observations.')}<pre>${esc(JSON.stringify(d.lines,null,2))}</pre><small>${esc(d.sourceObservationIds.join(', '))}</small></details></td></tr>`).join('')}</tbody></table></div>`:'<p>No billing documents yet. Receive readings and calculate a completed period.</p>';}
function cases(items){return items.length?items.map(c=>`<div class="record-row"><span>${esc(c.day)} · ${esc(c.reason)}<br><code>${esc(c.meter)}</code></span><div>${tag(c.status)} <button data-premise="${esc(c.premise)}">Open property</button></div></div>`).join(''):'<p>No received missing-read cases.</p>';}
function reads(items){return items.length?`<div class="scroll"><table><thead><tr><th>DAY</th><th>METER / SOURCE</th><th>QUANTITY</th><th>RECEIVED</th></tr></thead><tbody>${items.map(r=>`<tr><td>${esc(r.day)}</td><td><code>${esc(r.meter)}</code><br><small>${esc(r.id)}</small></td><td>${r.quantity===null?'Missing':esc(r.quantity)+' '+esc(r.unit)}</td><td>${esc(r.received_at)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No observations received into billing yet.</p>';}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-premise]').forEach(b=>b.onclick=()=>openProperty(b.dataset.premise));$('connection-form')?.addEventListener('submit',connectRuntime);}
async function action(which){if(busy||!summary)return;const context=capture(),body={townId:context.summary.town.id},start=$('bill-start')?.value,end=$('bill-end')?.value;busy=true;render();try{if(which==='advance'){await context.api('advance',{...body,expectedThrough:context.summary.state.through});if(!context.current())return;notice('Physical day committed. Receive the new readings to make them available to billing.');}if(which==='ingest'){if(context.virtualReady?.configured){if(!context.virtualReady.initialized){await context.api('virtual-systems/initialize',body);if(!context.current())return;}const r=await context.api('virtual-systems/ingest',body);if(!context.current())return;notice(`${fmt(r.imported)} observations received in actual Virtual Systems.`);}else{const r=await context.api('billing/ingest',body);if(!context.current())return;notice(`${fmt(r.received)} observations received in the local charge preview.`);}}if(which==='bill'){const r=await context.api('billing/run',{...body,start,end});if(!context.current())return;notice(`${fmt(r.issued)} documents issued; ${fmt(r.blocked)} blocked; ${fmt(r.unchanged)} already issued.`);}const updated=await context.api('summary');if(!context.current())return;summary=updated;await loadBilling(context);if(!context.current())return;$('map-status').textContent=`${catalog.find(t=>t.id===context.town)?.name} · ${fmt(summary.town.homes)} homes · ${fmt(summary.state.days)} days · ${fmt(summary.state.observations)} observations`;if(property)await openProperty(property);}catch(e){if(context.current())notice(e.message);}finally{if(context.current()){busy=false;render();}}}
async function loadQuality(){const context=capture();try{const report=await context.api('quality');if(page!=='quality'||!context.current())return;$('quality-results').innerHTML=`<h2>Saved-world checks</h2><pre>${esc(JSON.stringify(report,null,2))}</pre>`;}catch(e){if(context.current()&&page==='quality')notice(e.message);}}
async function openProperty(id){if(!summary)return;const context=capture(),ticket=++propertyVersion;property=id;$('property-body').innerHTML='<h2>Opening property…</h2>';$('property').show();try{const [record,billing]=await Promise.all([context.api('premises/'+encodeURIComponent(id)),context.api('billing?premise='+encodeURIComponent(id))]);if(!propertyCurrent(context,id,ticket))return;const p=record.premise;$('property-body').innerHTML=`<span class="eyebrow">PROPERTY & ACCOUNT</span><h2>${esc(p.address)}</h2>${row('Premise',id)}${billing.accounts.map(a=>row('Contract account',a.id)).join('')}${billing.customers.map(c=>row('Customer',c.name)).join('')}${row('Next physical day',record.through)}<h3>Physical meter records</h3>${record.assets.map(a=>`<div class="panel"><b>${esc(a.commodity)}</b>${row('Meter',a.id)}${row('Device',a.device)}${row('Condition',a.condition)}${row('Last observation',a.observed_quantity===null?'Missing':a.observed_quantity+' '+a.unit)}${row('Observation source',a.observation_id)}<button data-replace="${esc(a.id)}">Local physical meter replacement</button></div>`).join('')}<div id="property-vs"></div><details><summary>Local UtilitySim charge preview</summary>${documents(billing.documents)}</details><details><summary>Received meter observations (${fmt(billing.receivedReads)})</summary>${reads(billing.reads)}</details><p class="subtle">A replacement affects future readings. Historical missing readings stay missing; no truth-based estimates are inserted.</p>`;bind();$('property-body').querySelectorAll('[data-replace]').forEach(button=>button.onclick=()=>replacementForm(button.dataset.replace,context,id,ticket));if(virtualReady?.configured)await propertyVirtual(id,record,context,ticket);}catch(e){if(!propertyCurrent(context,id,ticket))return;$('property-body').innerHTML=`<h2>Records unavailable</h2><p>${esc(e.message)}</p>`;}}
function propertyCurrent(context,id,ticket){return context.current()&&property===id&&propertyVersion===ticket;}
async function propertyVirtual(id,record,context,ticket){
 const state=await context.api('virtual-systems?premise='+encodeURIComponent(id));if(!propertyCurrent(context,id,ticket))return;const box=$('property-vs');
 box.innerHTML=`<h3>Virtual Systems account</h3><p>${state.initialized?'Actual billing and independent receivables records.':'Initialize this town in the billing workspace to create its dedicated recipients.'}</p>${(state.invoices||[]).map(i=>`<div class="record-row"><span>${esc(i.id)}<br>${esc(i.account_id)}</span><b>${money(i.total_minor,i.currency)}</b></div>`).join('')}<details><summary>Received Virtual Systems observations</summary>${(state.receivedReadings||[]).map(r=>`<div class="record-row"><span>${esc(r.start)} · ${esc(r.installation_id)}<br><small>${esc(r.source_id)}</small></span><b>${esc(r.quantity)} ${esc(r.unit)} · ${esc(r.status)}</b></div>`).join('')}</details><button data-page="billing">Open billing & receivables</button>${state.initialized?record.assets.filter(a=>a.commodity==='water').map(a=>`<form class="panel" data-field="${esc(a.installation)}"><h3>Request a water-service investigation</h3><label>Reason<input name="reason" required placeholder="Describe the observed billing or supply issue"></label><button>Dispatch plumbing inspection / leak repair</button><p class="subtle">Creates an actual Virtual Systems investigation and authenticated field assignment. Only an existing leak can be repaired. The report requires separate review.</p></form>`).join(''):''}<h3>Saved field requests</h3>${(state.fieldRequests||[]).map((request,index)=>`<div class="record-row"><span>${esc(request.order.id)} · ${esc(request.order.status)}<br>${esc(request.reason)}</span><button data-resume-field="${index}">Open / resume saved request</button></div>`).join('')||'<p>No saved field requests.</p>'}<div id="field-result"></div>`;
 const current=()=>propertyCurrent(context,id,ticket);
 box.querySelectorAll('[data-resume-field]').forEach(button=>button.onclick=async()=>{if(!current())return;button.disabled=true;const request=state.fieldRequests[Number(button.dataset.resumeField)];try{const result=await context.api('virtual-systems/repair',{townId:context.summary.town.id,commandId:request.commandId,installationId:request.installationId,reason:request.reason});if(current())showFieldResult(result,context,id,ticket);}catch(error){if(current())notice(error.message);}finally{if(current())button.disabled=false;}});bind();box.querySelector('[data-page]').onclick=()=>{if(!current())return;$('property').close();property=null;propertyVersion++;navigate('billing');};box.querySelectorAll('[data-field]').forEach(form=>{const commandId=crypto.randomUUID();form.onsubmit=async e=>{e.preventDefault();if(!current())return;const button=form.querySelector('button');button.disabled=true;try{const result=await context.api('virtual-systems/repair',{townId:context.summary.town.id,commandId,installationId:form.dataset.field,reason:form.elements.reason.value});if(current())showFieldResult(result,context,id,ticket);}catch(error){if(current()){notice(error.message);button.disabled=false;}}};});
}
function showFieldResult(result,context,id,ticket){const current=()=>propertyCurrent(context,id,ticket),target=$('field-result');if(!current()||!target)return;target.innerHTML=`<div class="panel"><h3>Field report</h3>${row('Investigation',result.order?.id)}${row('Status',result.order?.status)}${row('Crew finding',result.order?.reports?.[0]?.outcome||'Awaiting report')}<details><summary>Authenticated field evidence</summary><pre>${esc(JSON.stringify(result,null,2))}</pre></details><form id="accept-field"><label>Review note<input name="note" required placeholder="Record your review of the received field report"></label><button>Accept received report</button></form><p>Advance the next physical day, then receive its observations in Virtual Systems to see the outcome in billing.</p></div>`;const form=$('accept-field');form.onsubmit=async e=>{e.preventDefault();if(!current())return;form.querySelector('button').disabled=true;try{const orderId=result.orderId||result.order?.id;await context.api('virtual-systems/accept-report',{townId:context.summary.town.id,orderId,note:form.elements.note.value});if(!current())return;notice('Field report reviewed in Virtual Systems.');form.remove();}catch(error){if(current()){notice(error.message);form.querySelector('button').disabled=false;}}};}
function replacementForm(meter,context,id,ticket){const current=()=>propertyCurrent(context,id,ticket);if(!current())return;const panel=document.createElement('form');panel.className='panel';panel.innerHTML=`<h3>Complete physical replacement</h3><p class="subtle">${esc(meter)}</p><label>Work order<input name="workOrder" required maxlength="200" value="WO-${Date.now()}"></label><label>Completion note<input name="note" required maxlength="1000" placeholder="What work was completed?"></label><button class="primary">Record completed work</button>`;const commandId=crypto.randomUUID(),device='DEVICE-'+crypto.randomUUID();panel.onsubmit=async e=>{e.preventDefault();if(!current())return;const button=panel.querySelector('button');button.disabled=true;try{const r=await context.api('billing/replace-meter',{townId:context.summary.town.id,commandId,meterId:meter,newDeviceId:device,workOrderId:panel.elements.workOrder.value,note:panel.elements.note.value});if(!current())return;notice(r.note);await openProperty(id);}catch(error){if(current()){notice(error.message);button.disabled=false;}}};$('property-body').append(panel);panel.scrollIntoView({behavior:'smooth'});}
$('menu').onclick=()=>{const hidden=document.body.classList.toggle('nav-hidden');$('menu').setAttribute('aria-expanded',String(!hidden));};$('close-property').onclick=()=>{$('property').close();property=null;propertyVersion++;};$('town').onchange=()=>{billingOffset=0;loadTown($('town').value);};
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('town-map').contentWindow)return;if(page==='map'&&summary&&property!==e.data?.premiseId&&e.data?.type==='atlas-premise'&&(!e.data.presetId||e.data.presetId===selected))openProperty(e.data.premiseId);if(e.data?.type==='atlas-runtime-ready')$('town-map').contentWindow.postMessage(mapConfig(),location.origin);});
async function initialize(){version++;busy=false;property=null;propertyVersion++;summary=null;bills=null;virtualReady=null;$('property').close();$('content')._virtualMarker=null;$('connection-status').textContent='Opening runtime…';render();const context=capture();try{let data;try{data=await context.api('catalog');}catch{if(!context.current())return;const r=await fetch('/presets/catalog.json');data=await r.json();}if(!context.current())return;catalog=data.presets;$('town').innerHTML=catalog.map(t=>`<option value="${esc(t.id)}">${esc(t.name)} · ${fmt(t.targetHomes)} homes${t.baked===false?' · configured':''}</option>`).join('');if(!catalog.some(t=>t.id===selected))selected=catalog.find(t=>t.id==='ashtown-5000')?.id||catalog[0].id;navigate(page);const loaded=await loadTown(selected);if(!loaded.current())return;const initial=params.get('premise');if(initial&&summary&&(!params.get('town')||params.get('town')===selected)){params.delete('premise');await openProperty(initial);}}catch(e){if(!context.current())return;notice(e.message);navigate('connections');}}
if(innerWidth<750)document.body.classList.add('nav-hidden');bind();initialize();
